BEGIN TRANSACTION;
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE "auth_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "first_name" varchar(150) NOT NULL);
CREATE TABLE "auth_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE "helpex_app_blogcategory" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(50) NOT NULL, "slug" varchar(50) NOT NULL UNIQUE, "description" text NOT NULL, "order" integer unsigned NOT NULL CHECK ("order" >= 0));
CREATE TABLE "helpex_app_blogpost" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(200) NOT NULL, "slug" varchar(200) NOT NULL UNIQUE, "featured_image" varchar(100) NULL, "excerpt" text NOT NULL, "content" text NOT NULL, "author" varchar(100) NOT NULL, "author_image" varchar(100) NULL, "tags" text NOT NULL CHECK ((JSON_VALID("tags") OR "tags" IS NULL)), "is_published" bool NOT NULL, "is_featured" bool NOT NULL, "view_count" integer unsigned NOT NULL CHECK ("view_count" >= 0), "order" integer unsigned NOT NULL CHECK ("order" >= 0), "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "category_id" bigint NULL REFERENCES "helpex_app_blogcategory" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "helpex_app_client" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL, "logo" varchar(100) NULL, "website" varchar(200) NOT NULL, "industry" varchar(100) NOT NULL, "description" text NOT NULL, "order" integer unsigned NOT NULL CHECK ("order" >= 0), "is_active" bool NOT NULL, "is_featured" bool NOT NULL, "created_at" datetime NOT NULL);
CREATE TABLE "helpex_app_contactmessage" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL, "email" varchar(254) NOT NULL, "subject" varchar(200) NOT NULL, "message" text NOT NULL, "is_read" bool NOT NULL, "created_at" datetime NOT NULL);
CREATE TABLE "helpex_app_herosection" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title_line_1" varchar(100) NOT NULL, "title_line_2" varchar(100) NOT NULL, "typing_texts" text NOT NULL CHECK ((JSON_VALID("typing_texts") OR "typing_texts" IS NULL)), "description" text NOT NULL, "cta_button_text" varchar(50) NOT NULL, "cta_button_url" varchar(100) NOT NULL, "secondary_cta_text" varchar(50) NOT NULL, "secondary_cta_url" varchar(100) NOT NULL, "stats_label_1" varchar(30) NOT NULL, "stats_number_1" varchar(10) NOT NULL, "stats_label_2" varchar(30) NOT NULL, "stats_number_2" varchar(10) NOT NULL, "stats_label_3" varchar(30) NOT NULL, "stats_number_3" varchar(10) NOT NULL, "badge_text" varchar(50) NOT NULL, "show_badge" bool NOT NULL, "is_active" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE "helpex_app_portfoliocategory" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(50) NOT NULL, "slug" varchar(50) NOT NULL UNIQUE, "order" integer unsigned NOT NULL CHECK ("order" >= 0));
CREATE TABLE "helpex_app_portfolioitem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(100) NOT NULL, "slug" varchar(100) NOT NULL UNIQUE, "description" text NOT NULL, "client_name" varchar(100) NOT NULL, "tags" text NOT NULL CHECK ((JSON_VALID("tags") OR "tags" IS NULL)), "order" integer unsigned NOT NULL CHECK ("order" >= 0), "is_active" bool NOT NULL, "created_at" datetime NOT NULL, "category_id" bigint NULL REFERENCES "helpex_app_portfoliocategory" ("id") DEFERRABLE INITIALLY DEFERRED, "image" varchar(100) NULL);
CREATE TABLE "helpex_app_processstep" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "step_number" integer unsigned NOT NULL CHECK ("step_number" >= 0), "title" varchar(100) NOT NULL, "description" text NOT NULL, "icon_class" varchar(100) NOT NULL, "order" integer unsigned NOT NULL CHECK ("order" >= 0), "is_active" bool NOT NULL);
CREATE TABLE "helpex_app_service" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(100) NOT NULL, "description" text NOT NULL, "short_description" varchar(200) NOT NULL, "icon_class" varchar(100) NOT NULL, "tags" text NOT NULL CHECK ((JSON_VALID("tags") OR "tags" IS NULL)), "order" integer unsigned NOT NULL CHECK ("order" >= 0), "is_active" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE "helpex_app_sitesettings" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "company_name" varchar(100) NOT NULL, "tagline" varchar(200) NOT NULL, "description" text NOT NULL, "email" varchar(254) NOT NULL, "phone" varchar(20) NOT NULL, "address" text NOT NULL, "social_twitter" varchar(200) NOT NULL, "social_instagram" varchar(200) NOT NULL, "social_linkedin" varchar(200) NOT NULL, "social_dribbble" varchar(200) NOT NULL, "primary_color" varchar(7) NOT NULL, "secondary_color" varchar(7) NOT NULL, "meta_title" varchar(200) NOT NULL, "meta_description" text NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE "helpex_app_teammember" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL, "role" varchar(100) NOT NULL, "bio" text NOT NULL, "photo" varchar(100) NULL, "email" varchar(254) NOT NULL, "order" integer unsigned NOT NULL CHECK ("order" >= 0), "is_active" bool NOT NULL);
CREATE TABLE "helpex_app_testimonial" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL, "role" varchar(100) NOT NULL, "company" varchar(100) NOT NULL, "quote" text NOT NULL, "avatar" varchar(100) NULL, "rating" integer unsigned NOT NULL CHECK ("rating" >= 0), "order" integer unsigned NOT NULL CHECK ("order" >= 0), "is_active" bool NOT NULL, "created_at" datetime NOT NULL);
CREATE UNIQUE INDEX "auth_group_permissions_group_id_permission_id_0cd325b0_uniq" ON "auth_group_permissions" ("group_id", "permission_id");
CREATE INDEX "auth_group_permissions_group_id_b120cbf9" ON "auth_group_permissions" ("group_id");
CREATE INDEX "auth_group_permissions_permission_id_84c5c92e" ON "auth_group_permissions" ("permission_id");
CREATE UNIQUE INDEX "auth_user_groups_user_id_group_id_94350c0c_uniq" ON "auth_user_groups" ("user_id", "group_id");
CREATE INDEX "auth_user_groups_user_id_6a12ed8b" ON "auth_user_groups" ("user_id");
CREATE INDEX "auth_user_groups_group_id_97559544" ON "auth_user_groups" ("group_id");
CREATE UNIQUE INDEX "auth_user_user_permissions_user_id_permission_id_14a6b632_uniq" ON "auth_user_user_permissions" ("user_id", "permission_id");
CREATE INDEX "auth_user_user_permissions_user_id_a95ead1b" ON "auth_user_user_permissions" ("user_id");
CREATE INDEX "auth_user_user_permissions_permission_id_1fbb5f2c" ON "auth_user_user_permissions" ("permission_id");
CREATE INDEX "django_admin_log_content_type_id_c4bce8eb" ON "django_admin_log" ("content_type_id");
CREATE INDEX "django_admin_log_user_id_c564eba6" ON "django_admin_log" ("user_id");
CREATE UNIQUE INDEX "django_content_type_app_label_model_76bd3d3b_uniq" ON "django_content_type" ("app_label", "model");
CREATE UNIQUE INDEX "auth_permission_content_type_id_codename_01ab375a_uniq" ON "auth_permission" ("content_type_id", "codename");
CREATE INDEX "auth_permission_content_type_id_2f476e4b" ON "auth_permission" ("content_type_id");
CREATE INDEX "django_session_expire_date_a5c62663" ON "django_session" ("expire_date");
CREATE INDEX "helpex_app_portfolioitem_category_id_bc915c7b" ON "helpex_app_portfolioitem" ("category_id");
CREATE INDEX "helpex_app_blogpost_category_id_4e75937f" ON "helpex_app_blogpost" ("category_id");
DELETE FROM "sqlite_sequence";
COMMIT;
